 uk:{search:'Пошук за питаннями та відповідями',all:'Усі',none:'Нічого не знайдено. Змініть запит або категорію.',shown:'Показано',of:'з',cats:{start:'Встановлення та версії',basics:'Основи NOAID',global:'EKF3 G.L.O.B.A.L.',order:'Н.А.К.А.З',modes:'Режими польоту',hardware:'Плати та параметри',logs:'Повідомлення та логи'}},
 en:{search:'Search questions and answers',all:'All',none:'Nothing found. Change the query or the category.',shown:'Shown',of:'of',cats:{start:'Install and versions',basics:'NOAID basics',global:'EKF3 G.L.O.B.A.L.',order:'O.R.D.E.R.',modes:'Flight modes',hardware:'Boards and parameters',logs:'Messages and logs'}}
